\set ON_ERROR_STOP on
BEGIN;
DO $vedu_wave3$
DECLARE
 spec jsonb; qspec jsonb;
 v_lesson bigint; v_quiz bigint; v_question bigint; v_answer bigint;
 v_count int; v_attempts int; v_i int; v_j int;
BEGIN
 FOR spec IN SELECT value FROM jsonb_array_elements($BANK_JSON$[{"course":47,"course_name":"Kiểm định phần mềm","order":2,"topic":"Tổng quan kiểm thử","questions":[{"text":"Kiểm thử phần mềm nhằm mục tiêu gì?","options":["Kiểm thử phát hiện lỗi, gỡ lỗi tìm nguyên nhân và sửa lỗi","Sản phẩm có được xây dựng đúng đặc tả không","Sau thay đổi để phát hiện chức năng cũ bị ảnh hưởng","Phát hiện sai lệch so với yêu cầu và đánh giá chất lượng"],"correct":3},{"text":"Verification trả lời câu hỏi nào?","options":["Điều kiện đầu vào, bước thực hiện và kết quả mong đợi","Không, kiểm thử chỉ làm giảm rủi ro lỗi chưa phát hiện","Sản phẩm có được xây dựng đúng đặc tả không","Sai sót có thể khiến phần mềm hoạt động không đúng yêu cầu"],"correct":2},{"text":"Validation trả lời câu hỏi nào?","options":["Kiểm thử phát hiện lỗi, gỡ lỗi tìm nguyên nhân và sửa lỗi","Sản phẩm có đáp ứng nhu cầu người dùng không","Điều kiện đầu vào, bước thực hiện và kết quả mong đợi","Không, kiểm thử chỉ làm giảm rủi ro lỗi chưa phát hiện"],"correct":1},{"text":"Một test case thường có thành phần nào?","options":["Sai sót có thể khiến phần mềm hoạt động không đúng yêu cầu","Hiệu năng, bảo mật và tính khả dụng","Điều kiện đầu vào, bước thực hiện và kết quả mong đợi","Hành vi hệ thống so với yêu cầu nghiệp vụ"],"correct":2},{"text":"Lỗi phần mềm (defect) là gì?","options":["Phát hiện sai lệch so với yêu cầu và đánh giá chất lượng","Sai sót có thể khiến phần mềm hoạt động không đúng yêu cầu","Hành vi hệ thống so với yêu cầu nghiệp vụ","Sau thay đổi để phát hiện chức năng cũ bị ảnh hưởng"],"correct":1},{"text":"Kiểm thử có chứng minh phần mềm không có lỗi không?","options":["Phát hiện sai lệch so với yêu cầu và đánh giá chất lượng","Hiệu năng, bảo mật và tính khả dụng","Không, kiểm thử chỉ làm giảm rủi ro lỗi chưa phát hiện","Kiểm thử phát hiện lỗi, gỡ lỗi tìm nguyên nhân và sửa lỗi"],"correct":2},{"text":"Kiểm thử hồi quy được thực hiện khi nào?","options":["Sai sót có thể khiến phần mềm hoạt động không đúng yêu cầu","Kiểm thử phát hiện lỗi, gỡ lỗi tìm nguyên nhân và sửa lỗi","Phát hiện sai lệch so với yêu cầu và đánh giá chất lượng","Sau thay đổi để phát hiện chức năng cũ bị ảnh hưởng"],"correct":3},{"text":"Kiểm thử chức năng tập trung vào yếu tố nào?","options":["Sau thay đổi để phát hiện chức năng cũ bị ảnh hưởng","Hành vi hệ thống so với yêu cầu nghiệp vụ","Sản phẩm có đáp ứng nhu cầu người dùng không","Sai sót có thể khiến phần mềm hoạt động không đúng yêu cầu"],"correct":1},{"text":"Kiểm thử phi chức năng tập trung vào yếu tố nào?","options":["Kiểm thử phát hiện lỗi, gỡ lỗi tìm nguyên nhân và sửa lỗi","Sau thay đổi để phát hiện chức năng cũ bị ảnh hưởng","Hiệu năng, bảo mật và tính khả dụng","Sản phẩm có đáp ứng nhu cầu người dùng không"],"correct":2},{"text":"Điểm khác biệt giữa kiểm thử và gỡ lỗi là gì?","options":["Không, kiểm thử chỉ làm giảm rủi ro lỗi chưa phát hiện","Sản phẩm có được xây dựng đúng đặc tả không","Kiểm thử phát hiện lỗi, gỡ lỗi tìm nguyên nhân và sửa lỗi","Sai sót có thể khiến phần mềm hoạt động không đúng yêu cầu"],"correct":2}]},{"course":47,"course_name":"Kiểm định phần mềm","order":3,"topic":"Quy trình và kế hoạch kiểm thử","questions":[{"text":"Bước đầu của lập kế hoạch kiểm thử là gì?","options":["Liên kết yêu cầu với test case và kết quả thực hiện","Xác định phạm vi, mục tiêu và rủi ro kiểm thử","Người phụ trách dự án và các bên liên quan theo quy trình","Cập nhật kế hoạch, phạm vi và test case tương ứng"],"correct":1},{"text":"Test plan thường ghi nội dung nào?","options":["Xác định phạm vi, mục tiêu và rủi ro kiểm thử","Cập nhật kế hoạch, phạm vi và test case tương ứng","Phạm vi, nguồn lực, lịch, môi trường và tiêu chí kết thúc","Liên kết yêu cầu với test case và kết quả thực hiện"],"correct":2},{"text":"Entry criteria nghĩa là gì?","options":["Liên kết yêu cầu với test case và kết quả thực hiện","Trạng thái chạy, lỗi phát hiện và kết quả test case","Người phụ trách dự án và các bên liên quan theo quy trình","Điều kiện cần đáp ứng trước khi bắt đầu một giai đoạn kiểm thử"],"correct":3},{"text":"Exit criteria nghĩa là gì?","options":["Phạm vi, nguồn lực, lịch, môi trường và tiêu chí kết thúc","Điều kiện để kết thúc một giai đoạn kiểm thử","Cập nhật kế hoạch, phạm vi và test case tương ứng","Xác định phạm vi, mục tiêu và rủi ro kiểm thử"],"correct":1},{"text":"Ma trận truy vết yêu cầu dùng để làm gì?","options":["Môi trường phần cứng, phần mềm và dữ liệu dùng để kiểm thử","Liên kết yêu cầu với test case và kết quả thực hiện","Cập nhật kế hoạch, phạm vi và test case tương ứng","Điều kiện cần đáp ứng trước khi bắt đầu một giai đoạn kiểm thử"],"correct":1},{"text":"Vì sao cần đánh giá rủi ro trong kiểm thử?","options":["Điều kiện để kết thúc một giai đoạn kiểm thử","Cập nhật kế hoạch, phạm vi và test case tương ứng","Người phụ trách dự án và các bên liên quan theo quy trình","Ưu tiên kiểm thử phần có xác suất lỗi hoặc tác động cao"],"correct":3},{"text":"Test environment là gì?","options":["Liên kết yêu cầu với test case và kết quả thực hiện","Môi trường phần cứng, phần mềm và dữ liệu dùng để kiểm thử","Cập nhật kế hoạch, phạm vi và test case tương ứng","Trạng thái chạy, lỗi phát hiện và kết quả test case"],"correct":1},{"text":"Ai thường phê duyệt phạm vi kiểm thử?","options":["Điều kiện cần đáp ứng trước khi bắt đầu một giai đoạn kiểm thử","Trạng thái chạy, lỗi phát hiện và kết quả test case","Người phụ trách dự án và các bên liên quan theo quy trình","Ưu tiên kiểm thử phần có xác suất lỗi hoặc tác động cao"],"correct":2},{"text":"Test execution report ghi gì?","options":["Trạng thái chạy, lỗi phát hiện và kết quả test case","Điều kiện cần đáp ứng trước khi bắt đầu một giai đoạn kiểm thử","Liên kết yêu cầu với test case và kết quả thực hiện","Xác định phạm vi, mục tiêu và rủi ro kiểm thử"],"correct":0},{"text":"Khi yêu cầu thay đổi giữa dự án cần làm gì?","options":["Trạng thái chạy, lỗi phát hiện và kết quả test case","Xác định phạm vi, mục tiêu và rủi ro kiểm thử","Cập nhật kế hoạch, phạm vi và test case tương ứng","Điều kiện để kết thúc một giai đoạn kiểm thử"],"correct":2}]},{"course":47,"course_name":"Kiểm định phần mềm","order":4,"topic":"Thiết kế test case và test data","questions":[{"text":"Kỹ thuật phân vùng tương đương giúp gì?","options":["Phản ứng của hệ thống với đầu vào hoặc thao tác không hợp lệ","Chia miền dữ liệu thành lớp có hành vi kỳ vọng tương tự","Hệ thống có trạng thái và chuyển đổi trạng thái rõ ràng","Xác định tiêu chí so sánh kết quả thực tế"],"correct":1},{"text":"Kiểm thử giá trị biên tập trung vào đâu?","options":["Phản ứng của hệ thống với đầu vào hoặc thao tác không hợp lệ","Bao phủ trường hợp hợp lệ, không hợp lệ và tình huống biên","Các giá trị sát giới hạn đầu vào cho phép","17, 18 và 19"],"correct":2},{"text":"Với điều kiện tuổi từ 18 đến 60, giá trị nào kiểm tra biên dưới hợp lý?","options":["Chia miền dữ liệu thành lớp có hành vi kỳ vọng tương tự","Hệ thống có trạng thái và chuyển đổi trạng thái rõ ràng","17, 18 và 19","Các giá trị sát giới hạn đầu vào cho phép"],"correct":2},{"text":"Bảng quyết định phù hợp khi nào?","options":["Nhiều điều kiện kết hợp quyết định một hành động","Hệ thống có trạng thái và chuyển đổi trạng thái rõ ràng","Phản ứng của hệ thống với đầu vào hoặc thao tác không hợp lệ","Chia miền dữ liệu thành lớp có hành vi kỳ vọng tương tự"],"correct":0},{"text":"State transition testing thích hợp với hệ thống nào?","options":["Chia miền dữ liệu thành lớp có hành vi kỳ vọng tương tự","Các giá trị sát giới hạn đầu vào cho phép","Bao phủ tương tác từng cặp tham số với ít ca hơn toàn tổ hợp","Hệ thống có trạng thái và chuyển đổi trạng thái rõ ràng"],"correct":3},{"text":"Test data tốt cần đáp ứng yêu cầu nào?","options":["Bao phủ trường hợp hợp lệ, không hợp lệ và tình huống biên","Phản ứng của hệ thống với đầu vào hoặc thao tác không hợp lệ","Hệ thống có trạng thái và chuyển đổi trạng thái rõ ràng","Nhiều điều kiện kết hợp quyết định một hành động"],"correct":0},{"text":"Test case phải có expected result để làm gì?","options":["Bao phủ trường hợp hợp lệ, không hợp lệ và tình huống biên","Bao phủ tương tác từng cặp tham số với ít ca hơn toàn tổ hợp","Chia miền dữ liệu thành lớp có hành vi kỳ vọng tương tự","Xác định tiêu chí so sánh kết quả thực tế"],"correct":3},{"text":"Pairwise testing có mục đích gì?","options":["Bao phủ tương tác từng cặp tham số với ít ca hơn toàn tổ hợp","Bao phủ trường hợp hợp lệ, không hợp lệ và tình huống biên","Hệ thống có trạng thái và chuyển đổi trạng thái rõ ràng","Các giá trị sát giới hạn đầu vào cho phép"],"correct":0},{"text":"Negative testing kiểm tra điều gì?","options":["Chia miền dữ liệu thành lớp có hành vi kỳ vọng tương tự","Xác định tiêu chí so sánh kết quả thực tế","Phản ứng của hệ thống với đầu vào hoặc thao tác không hợp lệ","Các giá trị sát giới hạn đầu vào cho phép"],"correct":2},{"text":"Với ô nhập số nguyên 1..10, dữ liệu 11 thuộc nhóm nào?","options":["Chia miền dữ liệu thành lớp có hành vi kỳ vọng tương tự","Nhiều điều kiện kết hợp quyết định một hành động","Bao phủ trường hợp hợp lệ, không hợp lệ và tình huống biên","Ngoài biên trên, không hợp lệ"],"correct":3}]},{"course":47,"course_name":"Kiểm định phần mềm","order":5,"topic":"Unit test với NUnit/JUnit","questions":[{"text":"Unit test kiểm tra phạm vi nào?","options":["Chuẩn bị, thực thi rồi xác nhận kết quả","Một đơn vị logic nhỏ như phương thức hoặc hàm",".NET và C#","Không, độ bao phủ không bảo đảm chất lượng assertion"],"correct":1},{"text":"JUnit thường dùng cho ngôn ngữ nào?","options":["Chuẩn bị, thực thi rồi xác nhận kết quả","Java","Thay phụ thuộc bằng đối tượng giả lập có kiểm soát",".NET và C#"],"correct":1},{"text":"NUnit thường dùng cho hệ sinh thái nào?","options":[".NET và C#","Một đơn vị logic nhỏ như phương thức hoặc hàm","Mẫu số bằng 0","Tránh lỗi dây chuyền do thứ tự chạy hoặc trạng thái chia sẻ"],"correct":0},{"text":"Một assertion trong unit test dùng để làm gì?","options":["Dữ liệu và thiết lập chung phục vụ các bài test","Tránh lỗi dây chuyền do