ản với nhiều bộ dữ liệu Examples","Behavior-Driven Development","Kết quả có thể quan sát và kiểm chứng","Bối cảnh và trạng thái ban đầu"],"correct":3},{"text":"When thể hiện điều gì?","options":["Hành động hoặc sự kiện được thực hiện","Kết quả hành vi mong đợi","Mô tả hành vi nghiệp vụ bằng ngôn ngữ có cấu trúc","Tạo ngôn ngữ chung giữa nghiệp vụ, lập trình và kiểm thử"],"correct":0},{"text":"Then thể hiện điều gì?","options":["Mô tả hành vi nghiệp vụ bằng ngôn ngữ có cấu trúc","Kết quả hành vi mong đợi","Ánh xạ các bước Gherkin thành mã kiểm thử thực thi","Behavior-Driven Development"],"correct":1},{"text":"Scenario Outline giúp gì?","options":["Given, When, Then","Bối cảnh và trạng thái ban đầu","Chạy một kịch bản với nhiều bộ dữ liệu Examples","Kết quả hành vi mong đợi"],"correct":2},{"text":"Feature file có nhiệm vụ gì?","options":["Given, When, Then","Hành động hoặc sự kiện được thực hiện","Kết quả hành vi mong đợi","Mô tả hành vi nghiệp vụ bằng ngôn ngữ có cấu trúc"],"correct":3},{"text":"Step definition dùng để làm gì?","options":["Ánh xạ các bước Gherkin thành mã kiểm thử thực thi","Hành động hoặc sự kiện được thực hiện","Tạo ngôn ngữ chung giữa nghiệp vụ, lập trình và kiểm thử","Bối cảnh và trạng thái ban đầu"],"correct":0},{"text":"Lợi ích chính của BDD là gì?","options":["Kết quả có thể quan sát và kiểm chứng","Given, When, Then","Mô tả hành vi nghiệp vụ bằng ngôn ngữ có cấu trúc","Tạo ngôn ngữ chung giữa nghiệp vụ, lập trình và kiểm thử"],"correct":3},{"text":"Một bước Then tốt nên mô tả gì?","options":["Chạy một kịch bản với nhiều bộ dữ liệu Examples","Mô tả hành vi nghiệp vụ bằng ngôn ngữ có cấu trúc","Kết quả hành vi mong đợi","Kết quả có thể quan sát và kiểm chứng"],"correct":3}]},{"course":47,"course_name":"Kiểm định phần mềm","order":7,"topic":"Kiểm thử UI với Selenium IDE","questions":[{"text":"Selenium IDE chủ yếu dùng để làm gì?","options":["Tránh lần chạy trước ảnh hưởng kết quả lần sau","Ghi và phát lại thao tác kiểm thử trình duyệt","Xác định