 lõi nào?","options":["Tổng hợp các giá trị theo từng khóa","Map và Reduce","count hoặc collect","Resilient Distributed Dataset"],"correct":1},{"text":"Map trong MapReduce thường làm gì?","options":["filter hoặc map","Dữ liệu đến liên tục thay vì xử lý lô hữu hạn","count hoặc collect","Chuyển dữ liệu đầu vào thành các cặp khóa-giá trị trung gian"],"correct":3},{"text":"Reduce thường làm gì?","options":["count hoặc collect","Dữ liệu có lược đồ dạng cột và có tối ưu truy vấn","Dữ liệu đến liên tục thay vì xử lý lô hữu hạn","Tổng hợp các giá trị theo từng khóa"],"correct":3},{"text":"Shuffle trong MapReduce nhằm mục đích gì?","options":["Map và Reduce","filter hoặc map","Gom dữ liệu cùng khóa về nơi xử lý Reduce","Dữ liệu có lược đồ dạng cột và có tối ưu truy vấn"],"correct":2},{"text":"RDD trong Spark là gì?","options":["Chuyển dữ liệu đầu vào thành các cặp khóa-giá trị trung gian","Dữ liệu đến liên tục thay vì xử lý lô hữu hạn","Chỉ thực thi tính toán khi gặp action","Resilient Distributed Dataset"],"correct":3},{"text":"DataFrame trong Spark mang đặc tính gì?","options":["Map và Reduce","Gom dữ liệu cùng khóa về nơi xử lý Reduce","Dữ liệu có lược đồ dạng cột và có tối ưu truy vấn","Resilient Distributed Dataset"],"correct":2},{"text":"Lazy evaluation trong Spark nghĩa là gì?","options":["Chuyển dữ liệu đầu vào thành các cặp khóa-giá trị trung gian","Tổng hợp các giá trị theo từng khóa","Chỉ thực thi tính toán khi gặp action","count hoặc collect"],"correct":2},{"text":"Spark action có ví dụ nào?","options":["Tổng hợp các giá trị theo từng khóa","Dữ liệu có lược đồ dạng cột và có tối ưu truy vấn","count hoặc collect","Chỉ thực thi tính toán khi gặp action"],"correct":2},{"text":"Spark transformation có ví dụ nào?","options":["Chuyển dữ liệu đầu vào thành các cặp khóa-giá trị trung gian","Resilient Distributed Dataset","Map và Reduce","filter hoặc map"],"correct":3},{"text":"Streaming data khác batch data chủ yếu ở điểm nào?","options":["Dữ liệu đến liên tục thay vì xử lý lô hữu hạn","Gom dữ liệu cùng khóa về nơi xử lý Reduce","Tổng hợp các giá trị theo từng khóa","Dữ liệu có lược đồ dạng cột và có tối ưu truy vấn"],"correct":0}]},{"course":51,"course_name":"Nhập môn Big Data","order":6,"topic":"Phân lớp, hồi quy, lọc cộng tác","questions":[{"text":"Classification dự đoán dạng đầu ra nào?","options":["Giá trị số liên tục","Nhãn rời rạc","Người dùng hoặc đối tượng mới thiếu lịch sử tương tác","Tương tác hoặc sở thích của nhiều người dùng và đối tượng"],"correct":1},{"text":"Regression dự đoán dạng đầu ra nào?","options":["Đánh giá quá lạc quan vì thông tin test lọt vào train","Giá trị số liên tục","Tỷ lệ dự đoán dương đúng trên tất cả dự đoán dương","Mẫu huấn luyện có nhãn mục tiêu"],"correct":1},{"text":"Supervised learning cần dữ liệu nào?","options":["Tương tác hoặc sở thích của nhiều người dùng và đối tượng","Mẫu huấn luyện có nhãn mục tiêu","Người dùng hoặc đối tượng mới thiếu lịch sử tương tác","Tỷ lệ dự đoán dương đúng trên tất cả dự đoán dương"],"correct":1},{"text":"Collaborative filtering khai thác điều gì?","options":["Hồi quy dự đoán giá trị số","Phù hợp quá mức tập train và kém tổng quát trên dữ liệu mới","Tương tác hoặc sở thích của nhiều người dùng và đối tượng","Mẫu huấn luyện có nhãn mục tiêu"],"correct":2},{"text":"Cold start trong gợi ý là gì?","options":["Người dùng hoặc đối tượng mới thiếu lịch sử tương tác","Phù hợp quá mức tập train và kém tổng quát trên dữ liệu mới","Tương tác hoặc sở thích của nhiều người dùng và đối tượng","Hồi quy dự đoán giá trị số"],"correct":0},{"text":"Precision đo điều gì trong phân loại?","options":["Tương tác hoặc sở thích của nhiều người dùng và đối tượng","Mẫu huấn luyện có nhãn mục tiêu","Giá trị số liên tục","Tỷ lệ dự đoán dương đúng trên tất cả dự đoán dương"],"correct":3},{"text":"Recall đo điều gì trong phân loại?","options":["Tương tác hoặc sở thích của nhiều người dùng và đối tượng","Tỷ lệ dự đoán dương đúng trên tất cả dự đoán dương","Hồi quy dự đoán giá trị số","Tỷ lệ dương tính thật được phát hiện trên mọi dương tính thật"],"correct":3},{"text":"Overfitting là gì?","options":["Phù hợp quá mức tập train và kém tổng quát trên dữ liệu mới","Người dùng hoặc đối tượng mới thiếu lịch sử tương tác","Giá trị số liên tục","Nhãn rời rạc"],"correct":0},{"text":"Train-test leakage gây vấn đề gì?","options":["Nhãn rời rạc","Giá trị số liên tục","Phù hợp quá mức tập train và kém tổng quát trên dữ liệu mới","Đánh giá quá lạc quan vì thông tin test lọt vào train"],"correct":3},{"text":"Metric RMSE thường dùng cho tác vụ nào?","options":["Đánh giá quá lạc quan vì thông tin test lọt vào train","Hồi quy dự đoán giá trị số","Phù hợp quá mức tập train và kém tổng quát trên dữ liệu mới","Giá trị số liên tục"],"correct":1}]}]$BANK_JSON$::jsonb) LOOP
   SELECT l.lesson_id INTO STRICT v_lesson
   FROM lms.lessons l JOIN lms.courses c ON c.course_id=l.course_id
   WHERE c.course_id=(spec->>'course')::bigint
     AND c.course_name=spec->>'course_name'
     AND l.lesson_order=(spec->>'order')::integer
     AND l.is_published=true AND l.is_deleted=false;
   SELECT q.quiz_id INTO STRICT v_quiz
   FROM assessment.quizzes q
   WHERE q.lesson_id=v_lesson
     AND q.course_id=(spec->>'course')::bigint
     AND q.is_published=true AND q.is_deleted=false;
   SELECT COUNT(*) INTO v_count FROM assessment.questions WHERE quiz_id=v_quiz;
   IF v_count NOT IN (3,10) THEN
     RAISE EXCEPTION 'Quiz % has % questions rather than 3 or 10',v_quiz,v_count;
   END IF;
   SELECT COUNT(*) INTO v_attempts FROM assessment.quiz_attempts WHERE quiz_id=v_quiz;
   IF v_count=3 THEN
     IF v_attempts=0 THEN
       FOR v_i IN 1..3 LOOP
         qspec:=spec->'questions'->(v_i-1);
         SELECT question_id INTO STRICT v_question
         FROM assessment.questions WHERE quiz_id=v_quiz AND question_order=v_i;
         IF (SELECT COUNT(*) FROM assessment.answers WHERE question_id=v_question)<>4 THEN
           RAISE EXCEPTION 'Question %: expected exactly 4 answers',v_question;
         END IF;
         UPDATE assessment.questions SET question_text=qspec->>'text',
           question_type='SINGLE_CHOICE',points=1 WHERE question_id=v_question;
         FOR v_j IN 1..4 LOOP
           SELECT answer_id INTO STRICT v_answer
           FROM assessment.answers WHERE question_id=v_question AND answer_order=v_j;
           UPDATE assessment.answers
           SET answer_text=qspec->'options'->>(v_j-1),
             is_correct=((qspec->>'correct')::int=(v_j-1))
           WHERE answer_id=v_answer;
         END LOOP;
       END LOOP;
     ELSE
       RAISE NOTICE 'Quiz % has % prior attempts; preserve old questions 1..3',v_quiz,v_attempts;
     END IF;
     FOR v_i IN 4..10 LOOP
       qspec:=spec->'questions'->(v_i-1);
       INSERT INTO assessment.questions(quiz_id,question_text,question_type,question_order,points)
       VALUES(v_quiz,qspec->>'text','SINGLE_CHOICE',v_i,1)
       RETURNING question_id INTO v_question;
       FOR v_j IN 1..4 LOOP
         INSERT INTO assessment.answers(question_id,answer_text,is_correct,answer_order)
         VALUES(v_question,qspec->'options'->>(v_j-1),
           ((qspec->>'correct')::int=(v_j-1)),v_j);
       END LOOP;
     END LOOP;
   ELSE
     FOR v_i IN 4..10 LOOP
       qspec:=spec->'questions'->(v_i-1);
       IF NOT EXISTS(SELECT 1 FROM assessment.questions
         WHERE quiz_id=v_quiz AND question_order=v_i AND question_text=qspec->>'text') THEN
         RAISE EXCEPTION 'Quiz % question % differs. Refuse overwrite.',v_quiz,v_i;
       END IF;
     END LOOP;
   END IF;
   IF EXISTS (
     SELECT 1 FROM assessment.questions qu WHERE qu.quiz_id=v_quiz
       AND (SELECT COUNT(*) FROM assessment.answers a WHERE a.question_id=qu.question_id)<>4
   ) THEN RAISE EXCEPTION 'Quiz % has question with invalid answer count',v_quiz; END IF;
   UPDATE assessment.quizzes
   SET updated_at=now(),time_limit_seconds=GREATEST(COALESCE(time_limit_seconds,0),900)
   WHERE quiz_id=v_quiz;
 END LOOP;
END;
$vedu_wave3$;
COMMIT;
